  constructor() {
    this.answers = {};
    this.init();
  }

  init() {
    this.setupEventListeners();
    this.loadAnswers();
  }

  setupEventListeners() {
    const form = document.getElementById('quizForm');
    const submitBtn = document.getElementById('submitBtn');
    const resetBtn = document.getElementById('resetBtn');

    submitBtn.addEventListener('click', (e) => this.handleSubmit(e));
    resetBtn.addEventListener('click', (e) => this.handleReset(e));

    // Add change listeners to all checkboxes
    const checkboxes = document.querySelectorAll('input[type="checkbox"]');
    checkboxes.forEach((checkbox) => {
      checkbox.addEventListener('change', () => this.saveAnswers());
    });
  }

  saveAnswers() {
    const questions = document.querySelectorAll('.form-field');
    this.answers = {};

    questions.forEach((field, index) => {
      const questionId = `q${index + 1}`;
      const checkedBoxes = field.querySelectorAll('input[type="checkbox"]:checked');
      this.answers[questionId] = Array.from(checkedBoxes).map((box) => box.value);
    });

    // Persist to localStorage
    localStorage.setItem('quizAnswers', JSON.stringify(this.answers));
  }

  loadAnswers() {
    const saved = localStorage.getItem('quizAnswers');
    if (saved) {
      this.answers = JSON.parse(saved);
      // Restore checkboxes from saved answers
      const checkboxes = document.querySelectorAll('input[type="checkbox"]');
      checkboxes.forEach((checkbox) => {
        const questionNum = checkbox
          .closest('.form-field')
          .getAttribute('data-question-id');
        if (this.answers[questionNum] && this.answers[questionNum].includes(checkbox.value)) {
          checkbox.checked = true;
        }
      });
    }
  }

  handleSubmit(e) {
    e.preventDefault();

    // Validate that at least one answer is selected
    if (Object.keys(this.answers).length === 0 || Object.values(this.answers).every((ans) => ans.length === 0)) {
      this.showMessage('Please select at least one answer for each question.', 'error');
      return;
    }

    // Show success message with summary
    const summary = this.generateSummary();
    this.showMessage(`✓ Quiz submitted! You selected ${summary} answer combinations.`, 'success');
  }

  handleReset(e) {
    e.preventDefault();
    this.answers = {};
    localStorage.removeItem('quizAnswers');

    // Uncheck all checkboxes
    const checkboxes = document.querySelectorAll('input[type="checkbox"]');
    checkboxes.forEach((checkbox) => {
      checkbox.checked = false;
    });

    // Clear message
    const messageDiv = document.getElementById('message');
    if (messageDiv) {
      messageDiv.remove();
    }
  }

  generateSummary() {
    return Object.values(this.answers).filter((ans) => ans.length > 0).length;
  }

  showMessage(text, type) {
    // Remove existing message if any
    const existingMessage = document.getElementById('message');
    if (existingMessage) {
      existingMessage.remove();
    }

    const messageDiv = document.createElement('div');
    messageDiv.id = 'message';
    messageDiv.className = `message ${type}`;
    messageDiv.textContent = text;

    const buttonContainer = document.querySelector('.button-container');
    buttonContainer.parentNode.insertBefore(messageDiv, buttonContainer.nextSibling);
  }
}

// Initialize quiz when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  new QuizApp();
});
